text:
{
  "outline": [
    {
      "title": "极限：微积分的地基",
      "summary": "学习数列极限和函数极限的定义（ε-N 和 ε-δ 语言）、两个重要极限、无穷小量比较与连续性，为后续导数与积分打下基础。",
      "kc_names": ["数列极限", "函数极限", "两个重要极限", "无穷小量"]
    },
    {
      "title": "导数：变化率的精确刻画",
      "summary": "掌握导数的定义与几何意义、基本初等函数导数表、求导法则（四则、复合、反函数）、高阶导数与隐函数求导，是微分学的核心运算。",
      "kc_names": ["导数", "基本初等函数导数表", "求导法则", "高阶导数"]
    },
    {
      "title": "微分中值定理：连接导数与函数性质",
      "summary": "学习罗尔、拉格朗日、柯西三大中值定理及洛必达法则，它们是证明不等式、判断单调性和求极限的重要工具。",
      "kc_names": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理", "洛必达法则"]
    },
    {
      "title": "泰勒公式：用多项式逼近函数",
      "summary": "理解泰勒多项式与余项（佩亚诺、拉格朗日），掌握常用函数的麦克劳林展开，并应用于近似计算与求极限。",
      "kc_names": ["泰勒公式"]
    },
    {
      "title": "积分：微分的逆运算与面积计算",
      "summary": "从不定积分与基本积分表出发，学习换元积分法和分部积分法，再过渡到定积分的定义、性质、牛顿-莱布尼茨公式及其应用。",
      "kc_names": ["不定积分", "换元积分法", "分部积分法", "定积分"]
    }
  ],
  "glossary": [
    {"term": "数列极限", "definition": "当 $n$ 无限增大时，数列 $a_n$ 无限趋近于常数 $A$，则称 $A$ 为数列的极限。"},
    {"term": "函数极限", "definition": "当 $x$ 无限接近 $x_0$ 时，$f(x)$ 无限趋近于常数 $A$，则称 $A$ 为函数在 $x_0$ 处的极限。"},
    {"term": "导数", "definition": "函数在某点的瞬时变化率，即差商的极限，几何上表示切线的斜率。"},
    {"term": "微分中值定理", "definition": "在光滑曲线上，至少存在一点使得该点的切线平行于两端点的连线，包括罗尔、拉格朗日和柯西定理。"},
    {"term": "泰勒公式", "definition": "用多项式近似表示函数，并给出误差估计的公式，是近似计算和求极限的有力工具。"},
    {"term": "不定积分", "definition": "导数的逆运算，求原函数的全体，结果是一个函数族。"},
    {"term": "定积分", "definition": "黎曼和的极限，用于计算曲线下的面积、弧长、体积等，由牛顿-莱布尼茨公式与不定积分关联。"},
    {"term": "洛必达法则", "definition": "当极限为 $0/0$ 或 $\\infty/\\infty$ 型时，可通过分子分母分别求导再求极限的方法。"}
  ],
  "suggested_questions": [
    "如何用 ε-N 语言证明数列 $1/n$ 的极限是 0？",
    "拉格朗日中值定理与罗尔定理有什么关系？",
    "洛必达法则适用于哪些类型的极限？使用时需要注意什么？",
    "如何用换元积分法计算 $\\int \\sin(2x) dx$？",
    "泰勒公式中的佩亚诺余项和拉格朗日余项有什么区别？"
  ]
}
